DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM address_expected e LEFT JOIN public.museums m USING(id) WHERE m.id IS NULL OR m.address IS DISTINCT FROM e.address) THEN RAISE EXCEPTION 'Address source changed; refresh review first'; END IF;
END $$;
UPDATE public.museums m SET address_en=e.address_en FROM address_expected e
WHERE m.id=e.id AND m.address IS NOT DISTINCT FROM e.address AND NULLIF(btrim(m.address_en),'') IS NULL;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM address_expected e JOIN public.museums m USING(id) JOIN address_before b USING(id)
 WHERE m.address_en IS DISTINCT FROM CASE WHEN NULLIF(btrim(b.original->>'address_en'),'') IS NOT NULL THEN b.original->>'address_en' ELSE e.address_en END)
 THEN RAISE EXCEPTION 'Address translation mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM address_before b JOIN public.museums m USING(id)
 WHERE to_jsonb(m)-ARRAY['address_en','updated_at'] IS DISTINCT FROM b.original-ARRAY['address_en','updated_at'])
 THEN RAISE EXCEPTION 'Unrequested columns changed'; END IF;
 IF (SELECT count(*) FROM public.museums)<>(SELECT count(*) FROM address_before)
 THEN RAISE EXCEPTION 'Row count changed'; END IF;
END $$;
SELECT jsonb_build_object('expected',(SELECT count(*) FROM address_expected),'verified',(SELECT count(*) FROM address_expected e JOIN public.museums m USING(id) WHERE m.address_en=e.address_en),'total_rows',(SELECT count(*) FROM public.museums),'other_columns_preserved',true) AS verification;
COMMIT;
